"""Additional read-only delivery review of archived FIELD coordinate quantization and scopes."""
from t2_tilt_g0_core import ROOT,OUT,LOCAL,RES,FREQ,read,rows,dump,table,sha,utc
from t2_tilt_g0_audit import mod_independent
import numpy as np,math,json,shutil

def main():
 results=[];detail=[];prov=read(OUT/'PROVIDER_PROVENANCE.json');allcoords=rows(OUT/'ARRAY_GEOMETRY_TABLE.csv');summary=rows(OUT/'FORWARD_CATALOGUE_NUMERICAL_STABILITY.csv');shape=[]
 for f in FREQ:
  z,phi,k=mod_independent(LOCAL/'modal'/f't2_f{int(f)}_n160001.mod');p=phi[int(np.argmin(abs(z-200)))];data=np.load(OUT/f'FIELD_COMPARISON_f{int(f)}.npz');meta=rows(OUT/f'FIELD_POINTS_f{int(f)}.csv');calculated=[];rdiff=[];zdiff=[]
  for r in meta:
   zi=int(np.argmin(abs(z-float(r['returned_z_m']))));rho=float(r['returned_range_m']);calc=np.sum(p*phi[zi]*np.sqrt(2*math.pi/(k*rho))*np.exp(-1j*k*rho-1j*math.pi/4));calculated.append(calc)
   a=next(t for t in allcoords if t['resource']==r['resource'] and t['channel']==r['channel']);state=prov['FIELD_plan']['states'][int(r['state'])];rr=math.hypot(state[0]*1000*math.cos(math.radians(state[1]))-float(a['x_m']),state[0]*1000*math.sin(math.radians(state[1]))-float(a['y_m']));rdiff.append(rho-rr);zdiff.append(float(r['returned_z_m'])-float(a['z_m']))
  actual=np.array(calculated);obs=data['FIELD'];c=np.vdot(actual,obs)/np.vdot(actual,actual);e=float(np.linalg.norm(obs-c*actual)/np.linalg.norm(obs));orig=np.vdot(data['pred'],obs)/np.vdot(data['pred'],data['pred']);eold=float(np.linalg.norm(obs-orig*data['pred'])/np.linalg.norm(obs));results.append({'frequency_hz':int(f),'original_registered_coordinate_error':eold,'cold_at_FIELD_saved_float32_ranges_error':e,'max_range_storage_quantization_m':float(np.max(abs(np.array(rdiff)))),'max_depth_storage_quantization_m':float(np.max(abs(np.array(zdiff)))),'factor_count':1,'formal_forward_gate_changed':False,'new_FIELD_calls':0})
  for res in prov['FIELD_plan']['resources']:
   mask=np.array([r['resource']==res for r in meta]);detail.append({'frequency_hz':int(f),'resource':res,'original_global_scalar_local_error':float(np.linalg.norm(obs[mask]-orig*data['pred'][mask])/np.linalg.norm(obs[mask])),'saved_range_global_scalar_local_error':float(np.linalg.norm(obs[mask]-c*actual[mask])/np.linalg.norm(obs[mask])),'global_scalar_not_independently_fitted':True})
 for r in summary:
  ee=np.load(LOCAL/f"SHAPE_ERROR_{r['resource']}_{r['catalogue']}.npy");fi=list(FREQ).index(float(r['frequency_hz']));h=np.load(LOCAL/'replicas'/f"{r['resource']}_{r['catalogue']}_n160001.npy",mmap_mode='r');norm=np.linalg.norm(h[:,fi],axis=-1);threshold=float(r['limit']);idx=int(r['max_error_candidate_id']);shape.append({'resource':r['resource'],'catalogue':r['catalogue'],'frequency_hz':float(r['frequency_hz']),'checked_candidate_vectors':len(ee),'individual_vectors_above_0p2pct':int(np.sum(ee[:,fi]>threshold)),'worst_error_vector_norm':float(norm[idx]),'median_vector_norm':float(np.median(norm)),'worst_to_median_norm_ratio':float(norm[idx]/np.median(norm)),'all_kept_not_weak_filtered':True})
 table(OUT/'FIELD_STORAGE_QUANTIZATION_COLD_DIAGNOSTIC.csv',results);table(OUT/'FIELD_RESOURCE_DETAIL_SAME_GLOBAL_FACTOR.csv',detail);table(OUT/'FORWARD_WEAK_FIELD_AND_FAILURE_COUNTS.csv',shape)
 dump(OUT/'VALIDATION_SCOPE.json',{'scope':'forward controls and archived modal/field/candidate reconstruction only','formal_calibration_records':0,'formal_test_records':0,'waveform_DFT_MC_candidate_acceptance_boundaries':'NOT_EVALUATED','zero_DFT_errors_in_original_validation':'ZERO_CHECKS_NOT_A_PRECISION_CLAIM','zero_acceptance_flips':'ZERO_CHECKS_NOT_A_BOUNDARY_CERTIFICATE','pairing_invariance':'design and geometry controls only; no received records generated','additional_FIELD_review':'single float32 saved-range cold diagnostic, no formal threshold replacement or new solver','independent_checks':read(OUT/'VALIDATION.json')['checks'],'FIELD_saved_coordinates_max_error':max(x['cold_at_FIELD_saved_float32_ranges_error'] for x in results),'R4_percent':0})
 # Copy all required small raw propagation artifacts, keep large replica arrays on D with hash index.
 dest=OUT/'solver_archive';dest.mkdir(exist_ok=True)
 for p in (LOCAL/'modal').iterdir():
  if p.is_file() and (p.suffix in ['.mod','.prt','.shd','.txt']) and (not p.name.startswith('t2_field') or p.suffix in ['.shd','.txt']):shutil.copyfile(p,dest/p.name)
 archive=[{'path':str(p),'bytes':p.stat().st_size,'SHA256':sha(p)} for p in LOCAL.rglob('*') if p.is_file()];table(OUT/'LOCAL_ARCHIVE_INDEX.csv',archive)
 total=sum(p.stat().st_size for p in LOCAL.rglob('*') if p.is_file())+sum(p.stat().st_size for p in OUT.rglob('*') if p.is_file());dump(OUT/'BUDGET_AND_DELIVERY.json',{'science_wall_s':read(OUT/'EXECUTION_FAILURE.json')['science_wall_s'],'peak_RSS_bytes':max(r['peak_RSS_bytes'] for r in read(OUT/'EXECUTION_PROCESSES.json')),'new_D_bytes_at_delivery':total,'new_git_result_bytes':sum(p.stat().st_size for p in OUT.rglob('*') if p.is_file()),'limits':{'science_seconds':21600,'RSS':8*1024**3,'D_new':32*1024**3,'Git_new':512*1024**2},'KRAKEN':6,'FIELD':3,'formal_calibration_base_records':0,'formal_test_base_innovations':0,'formal_test_configs':0,'forward_resource_candidate_states':sum(int(r['candidates']) for r in summary)//3,'forward_frequency_spatial_vectors':sum(int(r['candidates']) for r in summary),'formal_scoring_and_truth_retention':'NOT_EVALUATED'})
 dump(OUT/'NOT_EVALUATED_PHASES.json',{'reason':'FORWARD_NUMERIC_NOT_ADMITTED, all9resources/both completecatalogues fail registered0.002 worst-case shape gate','calibration_waveforms_DFT_thresholds':'NOT_EVALUATED','test_waveforms_DFT_fullcatalogue_inference':'NOT_EVALUATED','A_B_signal_truth_retention_envelope_point_error':'NOT_EVALUATED','C0_C1_SNR_depth_angle_performance_comparison':'NOT_EVALUATED','no_fake_ZERO_or_PASS_for_unrun_tests':True,'scientific_new_runs_after_stop':0,'state':'STOP'})
 print('FIELD storage cold diagnostic',results,flush=True)
if __name__=='__main__':main()